-- Design draft, target PostgreSQL 17/18. UUIDv7 generated by application.
CREATE SCHEMA IF NOT EXISTS archive;
CREATE SCHEMA IF NOT EXISTS memory;
CREATE SCHEMA IF NOT EXISTS runtime;
CREATE SCHEMA IF NOT EXISTS analytics;

CREATE TABLE archive.users (
 user_id uuid PRIMARY KEY, username text NOT NULL, display_name text,
 status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')),
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT username_nonempty CHECK(length(btrim(username))>0)
);
CREATE UNIQUE INDEX users_username_lower_uq ON archive.users(lower(username));

CREATE TABLE archive.projects (
 project_id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES archive.users(user_id),
 name text NOT NULL CHECK(length(btrim(name))>0), description text, instructions text,
 status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz,
 UNIQUE(user_id,project_id)
);

CREATE TABLE archive.conversations (
 conversation_id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES archive.users(user_id),
 project_id uuid, parent_conversation_id uuid, branch_point_message_id uuid,
 branch_point_revision_id uuid, title text NOT NULL DEFAULT 'New conversation',
 status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),
 next_message_ordinal bigint NOT NULL DEFAULT 1 CHECK(next_message_ordinal>0),
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 branched_at timestamptz, archived_at timestamptz,
 UNIQUE(user_id,conversation_id),
 FOREIGN KEY(user_id,project_id) REFERENCES archive.projects(user_id,project_id),
 FOREIGN KEY(user_id,parent_conversation_id) REFERENCES archive.conversations(user_id,conversation_id),
 CHECK(parent_conversation_id IS NULL OR parent_conversation_id<>conversation_id),
 CHECK ((parent_conversation_id IS NULL AND branched_at IS NULL AND branch_point_message_id IS NULL AND branch_point_revision_id IS NULL)
     OR (parent_conversation_id IS NOT NULL AND branched_at IS NOT NULL)),
 CHECK((branch_point_message_id IS NULL)=(branch_point_revision_id IS NULL))
);

CREATE TABLE archive.messages (
 message_id uuid PRIMARY KEY, user_id uuid NOT NULL, conversation_id uuid NOT NULL,
 message_ordinal bigint NOT NULL CHECK(message_ordinal>0),
 role text NOT NULL CHECK(role IN ('system','user','assistant','tool')),
 status text NOT NULL CHECK(status IN ('pending','completed','interrupted','failed')),
 current_revision_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(user_id,message_id), UNIQUE(user_id,message_id,conversation_id),
 UNIQUE(conversation_id,message_ordinal),
 FOREIGN KEY(user_id,conversation_id) REFERENCES archive.conversations(user_id,conversation_id),
 CHECK(jsonb_typeof(metadata)='object')
);

CREATE TABLE archive.message_revisions (
 revision_id uuid PRIMARY KEY, user_id uuid NOT NULL, message_id uuid NOT NULL,
 revision_number integer NOT NULL CHECK(revision_number>0),
 content jsonb NOT NULL, content_hash text NOT NULL, edit_reason text,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(user_id,revision_id), UNIQUE(user_id,message_id,revision_id),
 UNIQUE(message_id,revision_number),
 FOREIGN KEY(user_id,message_id) REFERENCES archive.messages(user_id,message_id),
 CHECK(jsonb_typeof(content)='object')
);
ALTER TABLE archive.messages ADD CONSTRAINT message_current_revision_fk
 FOREIGN KEY(user_id,message_id,current_revision_id)
 REFERENCES archive.message_revisions(user_id,message_id,revision_id)
 DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE archive.conversations ADD CONSTRAINT conversation_branch_point_fk
 FOREIGN KEY(user_id,branch_point_message_id,branch_point_revision_id)
 REFERENCES archive.message_revisions(user_id,message_id,revision_id)
 DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE archive.conversation_branch_revisions (
 user_id uuid NOT NULL, conversation_id uuid NOT NULL,
 inherited_ordinal bigint NOT NULL CHECK(inherited_ordinal>0),
 source_message_id uuid NOT NULL, source_revision_id uuid NOT NULL,
 PRIMARY KEY(conversation_id,inherited_ordinal), UNIQUE(conversation_id,source_message_id),
 FOREIGN KEY(user_id,conversation_id) REFERENCES archive.conversations(user_id,conversation_id),
 FOREIGN KEY(user_id,source_message_id,source_revision_id)
 REFERENCES archive.message_revisions(user_id,message_id,revision_id)
);

CREATE TABLE archive.attachments (
 attachment_id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES archive.users(user_id),
 filename text NOT NULL, media_type text NOT NULL, storage_uri text NOT NULL,
 size_bytes bigint NOT NULL CHECK(size_bytes>=0), sha256 text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(user_id,attachment_id)
);
CREATE TABLE archive.message_revision_attachments (
 user_id uuid NOT NULL, message_revision_id uuid NOT NULL, attachment_id uuid NOT NULL,
 position integer NOT NULL CHECK(position>=0),
 PRIMARY KEY(message_revision_id,attachment_id),
 UNIQUE(message_revision_id,position),
 FOREIGN KEY(user_id,message_revision_id) REFERENCES archive.message_revisions(user_id,revision_id),
 FOREIGN KEY(user_id,attachment_id) REFERENCES archive.attachments(user_id,attachment_id)
);
CREATE INDEX conversations_recent_idx ON archive.conversations(user_id,updated_at DESC);
CREATE INDEX conversations_project_idx ON archive.conversations(user_id,project_id,updated_at DESC);
CREATE INDEX conversations_parent_idx ON archive.conversations(user_id,parent_conversation_id);
CREATE INDEX message_revisions_history_idx ON archive.message_revisions(message_id,revision_number);
